import pandas as pd, pdfplumber, re, difflib, json
vendors = pd.read_excel('/root/vendors.xlsx')
vendor_names = vendors['name'].tolist()
vendor_map = {row['name']: row for _,row in vendors.iterrows()}
po_df = pd.read_csv('/root/purchase_orders.csv')
po_map = {row['po_number']: row for _,row in po_df.iterrows()}

def match_vendor(name):
    if name in vendor_map:
        return vendor_map[name], name
    matches = difflib.get_close_matches(name, vendor_names, n=1, cutoff=0.8)
    if matches:
        m = matches[0]
        return vendor_map[m], m
    return None, None

results=[]
with pdfplumber.open('/root/invoices.pdf') as p:
    for i,page in enumerate(p.pages,1):
        text = page.extract_text() or ''
        vendor = amount = iban = po = None
        for line in text.splitlines():
            m = re.search(r'^From:\s*(.*)', line)
            if m: vendor = m.group(1).strip()
            m = re.search(r'^Total\s*\$([0-9,]+\.\d{2})', line)
            if m: amount = float(m.group(1).replace(',',''))
            m = re.search(r'^Payment IBAN:\s*(.*)', line)
            if m: iban = m.group(1).strip()
            m = re.search(r'^PO Number:\s*(.*)', line)
            if m: po = m.group(1).strip()
        po_val = po if po not in (None,'') else None
        vendor_match, matched_name = match_vendor(vendor) if vendor else (None,None)
        reason = None
        if vendor_match is None:
            reason = 'Unknown Vendor'
        else:
            if iban != vendor_match['iban']:
                reason = 'IBAN Mismatch'
            else:
                if po_val is None or po_val not in po_map:
                    reason = 'Invalid PO'
                else:
                    po_row = po_map[po_val]
                    if abs(amount - po_row['amount']) > 0.01:
                        reason = 'Amount Mismatch'
                    else:
                        if po_row['vendor_id'] != vendor_match['id']:
                            reason = 'Vendor Mismatch'
        if reason:
            results.append({
                'invoice_page_number': i,
                'vendor_name': vendor,
                'invoice_amount': round(amount,2) if amount is not None else None,
                'iban': iban,
                'po_number': po_val,
                'reason': reason
            })
print('flagged', len(results))
print(json.dumps(results, indent=2))
